K.coin=(x,y,r,sym,col=[244,200,90],rot=0,line=false)=>{ctx.save();ctx.translate(x,y);ctx.scale(Math.abs(Math.cos(rot))*.9+.1,1);if(line){ctx.strokeStyle=rgba(col,1);ctx.lineWidth=r*.07;ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.stroke();ctx.beginPath();ctx.arc(0,0,r*.8,0,TAU);ctx.stroke()}else{const g=ctx.createLinearGradient(-r,-r,r,r);g.addColorStop(0,'#fff6cf');g.addColorStop(.5,rgba(col,1));g.addColorStop(1,'#8a5a0a');ctx.shadowColor='rgba(0,0,0,.4)';ctx.shadowBlur=30*S;ctx.shadowOffsetY=14*S;ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.strokeStyle='rgba(120,70,0,.6)';ctx.lineWidth=r*.06;ctx.beginPath();ctx.arc(0,0,r*.82,0,TAU);ctx.stroke()}
 if(sym==='R'){K.rupee(0,0,r*.9,line?rgba(col,1):'#7a4a00',r*.12)}else txt(sym,0,r*.04,{f:'Montserrat',w:900,size:r*1.1,fill:line?rgba(col,1):'#7a4a00'});ctx.restore()};
K.wing=(x,y,s,side,flap,col='#fff')=>{ctx.save();ctx.translate(x,y);ctx.scale(side,1);ctx.rotate(-flap*.5);ctx.fillStyle=col;for(let i=0;i<4;i++){ctx.save();ctx.rotate(-i*.22);ctx.beginPath();ctx.ellipse(s*.5,0,s*.55,s*.12,0,0,TAU);ctx.fill();ctx.restore()}ctx.restore()};
